import Foundation
import Testing

@testable import BackstageMesh

/// The Swift port, checked against fixtures generated by the Go reference.
///
/// Every literal here came from running Go, not from reasoning about it:
///
///     GATECRASH_UPDATE_FIXTURES=1 go test ./internal/mesh -run ConformanceFixture
///     go test ./internal/cuckoo -run HashVectorsForThePorts -v
///
/// If one stops matching, the two implementations have diverged, and the consequence is
/// not a failing test — it is a message that never arrives.
///
/// swift-testing rather than XCTest, because XCTest ships with Xcode and this has to run
/// on a machine with only the command-line tools, which is what CI has.

// MARK: fixtures, from internal/mesh/testdata/conformance.json

private let frameEncoded = "010101040102030405060708090a0b0c000068656c6c6f206d657368"
private let frameAAD = "010101000102030405060708090a0b0c0000"

// MARK: helpers

private func hex(_ data: Data) -> String {
    data.map { String(format: "%02x", $0) }.joined()
}

private func unhex(_ text: String) -> Data {
    var out = Data()
    var index = text.startIndex
    while index < text.endIndex {
        let next = text.index(index, offsetBy: 2)
        out.append(UInt8(text[index..<next], radix: 16)!)
        index = next
    }
    return out
}

private func messageID(_ value: UInt64) -> Data {
    var out = Data(count: 8)
    for i in 0..<8 { out[i] = UInt8(truncatingIfNeeded: value >> (8 * (7 - UInt64(i)))) }
    return out
}

/// A hand-driven clock, so nothing here sleeps and every run is identical.
private final class Clock {
    var millis: Int64 = 1_600_000_000_000
    func now() -> Int64 { millis }
    func advance(_ by: Int64) { millis += by }
}

@Suite("The frame, byte for byte")
struct FrameTests {

    @Test("encodes exactly as the Go reference does")
    func encodesLikeGo() throws {
        let frame = Frame(
            kind: .channel,
            flags: .priority,
            ttl: 4,
            id: messageID(0x0102_0304_0506_0708),
            channel: Data([9, 10, 11, 12]),
            body: Data("hello mesh".utf8)
        )

        #expect(hex(try frame.encode()) == frameEncoded)
        #expect(hex(frame.aad()) == frameAAD)
    }

    @Test("decodes what Go encoded")
    func decodesWhatGoEncoded() throws {
        let frame = try Frame.decode(unhex(frameEncoded))

        #expect(frame.kind == .channel)
        #expect(frame.isPriority)
        #expect(frame.ttl == 4)
        #expect(hex(frame.id) == "0102030405060708")
        #expect(hex(frame.channel) == "090a0b0c")
        #expect(String(decoding: frame.body, as: UTF8.self) == "hello mesh")
        #expect(frame.isFragment == false)
    }

    /// The single most important property in the codec. Every relay decrements the TTL, so
    /// a TTL inside the authenticated data would mean a frame failed to authenticate at
    /// the first hop and the mesh would not work at all.
    @Test("the authenticated data ignores the ttl")
    func aadIgnoresTheTTL() throws {
        let frame = Frame(kind: .channel, ttl: 4, id: messageID(1), body: Data("x".utf8))
        let hopped = try #require(frame.hop())

        #expect(hopped.ttl == 3)
        #expect(hex(frame.aad()) == hex(hopped.aad()))
        #expect(Frame(kind: .channel, ttl: 0, id: messageID(1)).hop() == nil)
    }

    /// A frame cannot be re-labelled into another channel, promoted to priority, or
    /// re-stitched into a different message without breaking its tag.
    @Test("every other header field is authenticated")
    func everyOtherFieldIsAuthenticated() {
        let base = Frame(
            kind: .channel, ttl: 6, id: messageID(1),
            channel: Data([1, 2, 3, 4]), body: Data("x".utf8))
        let aad = hex(base.aad())

        var relabelled = base
        relabelled.kind = .direct
        #expect(hex(relabelled.aad()) != aad)

        var promoted = base
        promoted.flags = .priority
        #expect(hex(promoted.aad()) != aad)

        var reidentified = base
        reidentified.id = messageID(2)
        #expect(hex(reidentified.aad()) != aad)

        var rechannelled = base
        rechannelled.channel = Data([9, 9, 9, 9])
        #expect(hex(rechannelled.aad()) != aad)

        var restitched = base
        restitched.flags = .fragment
        restitched.fragmentIndex = 1
        restitched.fragmentTotal = 2
        #expect(hex(restitched.aad()) != aad)
    }

    @Test("decode rejects what it should")
    func decodeRejects() {
        let valid = [UInt8](unhex(frameEncoded))

        #expect(throws: (any Error).self) { try Frame.decode(Data(valid[0..<4])) }

        var wrongVersion = valid
        wrongVersion[0] = 99
        #expect(throws: (any Error).self) { try Frame.decode(Data(wrongVersion)) }

        var pastTheLimit = valid
        pastTheLimit[3] = maxTTL + 1
        #expect(throws: (any Error).self) { try Frame.decode(Data(pastTheLimit)) }

        var unknownKind = valid
        unknownKind[1] = 42
        #expect(throws: (any Error).self) { try Frame.decode(Data(unknownKind)) }

        let oversized = Data([protocolVersion] + [UInt8](repeating: 0, count: maxFrame))
        #expect(throws: (any Error).self) { try Frame.decode(oversized) }

        var singleFragment = valid
        singleFragment[2] |= Flags.fragment.rawValue
        singleFragment[17] = 1
        #expect(throws: (any Error).self) { try Frame.decode(Data(singleFragment)) }

        var indexAtTotal = valid
        indexAtTotal[2] |= Flags.fragment.rawValue
        indexAtTotal[16] = 3
        indexAtTotal[17] = 3
        #expect(throws: (any Error).self) { try Frame.decode(Data(indexAtTotal)) }

        var positionWithoutFlag = valid
        positionWithoutFlag[17] = 3
        #expect(throws: (any Error).self) { try Frame.decode(Data(positionWithoutFlag)) }
    }

    /// Data can be a slice with a non-zero start index, and a radio callback hands you
    /// exactly that. Decoding one must not trap or read the wrong bytes.
    @Test("decodes a slice of a larger buffer")
    func decodesASlice() throws {
        let padded = Data([0xff, 0xff]) + unhex(frameEncoded) + Data([0xff])
        let slice = padded[2..<(padded.count - 1)]

        let frame = try Frame.decode(slice)
        #expect(hex(frame.id) == "0102030405060708")
        #expect(String(decoding: frame.body, as: UTF8.self) == "hello mesh")
    }
}

@Suite("Fragmentation")
struct FragmentTests {

    @Test("round-trips out of order, because fragments take different paths")
    func roundTripsOutOfOrder() throws {
        let body = Data((0..<600).map { UInt8($0 % 251) })
        let frames = try Frame.fragment(
            template: Frame(kind: .channel, id: messageID(1)), body: body)

        #expect(frames.count == 4)
        #expect(frames.allSatisfy { $0.isFragment })
        #expect(frames.allSatisfy { $0.size <= maxFrame })

        // Keyed on the message id alone, fragment two would look like a duplicate of
        // fragment one and the message would never arrive.
        #expect(Set(frames.map { hex($0.dedupKey) }).count == frames.count)

        let clock = Clock()
        let reassembler = Reassembler(now: clock.now)
        var complete: Frame?
        for index in [2, 0, 3, 1] {
            if let done = try reassembler.accept(frames[index]) { complete = done }
        }

        let assembled = try #require(complete)
        #expect(assembled.body == body)
        #expect(assembled.isFragment == false)
        #expect(assembled.fragmentTotal == 0)
    }

    @Test("an unfragmented frame completes immediately")
    func unfragmentedCompletesImmediately() throws {
        let clock = Clock()
        let reassembler = Reassembler(now: clock.now)
        let frame = Frame(kind: .channel, id: messageID(1), body: Data("short".utf8))
        #expect(try reassembler.accept(frame) != nil)
    }

    /// Everything here arrives from strangers, and an unbounded reassembly buffer on a
    /// phone in a crowd is a way for one person to exhaust everybody else's memory.
    @Test("reassembly is bounded")
    func reassemblyIsBounded() throws {
        let clock = Clock()
        let reassembler = Reassembler(limit: 2, now: clock.now)

        for i in 0..<10 {
            let frames = try Frame.fragment(
                template: Frame(kind: .channel, id: messageID(UInt64(i))),
                body: Data(repeating: 0, count: 400))
            _ = try reassembler.accept(frames[0])
        }
        #expect(reassembler.pending <= 2)

        #expect(throws: (any Error).self) {
            try Frame.fragment(
                template: Frame(kind: .channel, id: messageID(1)),
                body: Data(repeating: 0, count: maxFragments * maxBody + 1))
        }
    }

    @Test("partial messages expire")
    func partialMessagesExpire() throws {
        let clock = Clock()
        let reassembler = Reassembler(timeoutMillis: 30_000, now: clock.now)
        let frames = try Frame.fragment(
            template: Frame(kind: .channel, id: messageID(1)),
            body: Data(repeating: 0, count: 400))

        _ = try reassembler.accept(frames[0])
        #expect(reassembler.pending == 1)

        clock.advance(60_000)
        #expect(reassembler.pending == 0)
    }

    @Test("inconsistent fragments are rejected")
    func inconsistentFragmentsRejected() throws {
        let clock = Clock()
        let reassembler = Reassembler(now: clock.now)
        let frames = try Frame.fragment(
            template: Frame(kind: .channel, id: messageID(1)),
            body: Data(repeating: 0, count: 400))

        _ = try reassembler.accept(frames[0])
        // The same piece twice is not an error, just nothing new.
        #expect(try reassembler.accept(frames[0]) == nil)

        // A piece claiming a different total is either a bug or an attempt to corrupt a
        // reassembly in progress.
        var confused = frames[1]
        confused.fragmentTotal = 9
        #expect(throws: (any Error).self) { try reassembler.accept(confused) }
    }
}

@Suite("The dedup filter")
struct FilterTests {

    /// Unsigned 64-bit arithmetic is the easiest place in this protocol to get a plausible
    /// wrong answer, and a wrong bucket index does not look like a bug — it looks like a
    /// mesh with a worse delivery rate.
    @Test("the hashing agrees with Go")
    func hashingAgreesWithGo() {
        #expect(String(format: "%016lx", splitmix(0)) == "e220a8397b1dcdaf")
        #expect(String(format: "%016lx", splitmix(1)) == "910a2dec89025cc1")
        #expect(String(format: "%016lx", splitmix(2)) == "975835de1c9756ce")
        #expect(String(format: "%016lx", splitmix(UInt64.max)) == "e4d971771b652c20")

        #expect(String(format: "%016lx", fnv1a(Data())) == "c3817c016ba4ff30")
        #expect(String(format: "%016lx", fnv1a(Data("gatecrash".utf8))) == "3c3fe25f978210f0")
        #expect(String(format: "%016lx", fnv1a(Data("backstage".utf8))) == "d31a88fed4c80c5f")
    }

    /// A false positive costs one unrelayed message. A false negative would turn dedup
    /// into a coin flip and put the ping-pong loop back.
    @Test("never forgets what it was told")
    func noFalseNegatives() {
        let filter = CuckooFilter(capacity: 4096)
        for i in 0..<3000 { #expect(filter.insert(messageID(UInt64(i)))) }
        for i in 0..<3000 { #expect(filter.contains(messageID(UInt64(i)))) }

        var positives = 0
        let probes = 100_000
        for i in 1_000_000..<(1_000_000 + probes) {
            if filter.contains(messageID(UInt64(i))) { positives += 1 }
        }
        let rate = Double(positives) / Double(probes)
        // At 8-bit fingerprints this would be around 3%.
        #expect(rate < 0.001, "false positive rate \(rate * 100)%")
    }

    /// Below 90% means the alternate-bucket derivation is wrong — most likely the
    /// fingerprint is being xored in without being mixed first, which confines both homes
    /// to one neighbourhood.
    @Test("reaches a useful load factor")
    func usefulLoadFactor() {
        let filter = CuckooFilter(capacity: 1 << 16)
        var inserted = 0
        while filter.insert(messageID(UInt64(inserted))) {
            inserted += 1
            if inserted > filter.capacity { break }
        }
        let load = Double(inserted) / Double(filter.capacity)
        #expect(load >= 0.90, "filled to \(load * 100)%")
    }

    @Test("seen ids expire, so the filter cannot fill up forever")
    func seenIdsExpire() {
        let clock = Clock()
        let seen = SeenSet(capacity: 1024, windowMillis: 600_000, now: clock.now)

        #expect(seen.seen(messageID(1)) == false)
        #expect(seen.seen(messageID(1)))

        // One window on: still in the previous generation.
        clock.advance(660_000)
        #expect(seen.seen(messageID(1)))

        clock.advance(660_000)
        _ = seen.seen(messageID(2))
        clock.advance(660_000)
        #expect(seen.seen(messageID(1)) == false)

        #expect(seen.bytes <= 64 * 1024)
    }

    /// The panic wipe. Somebody triple-tapping in a crowd wants no trace of what their
    /// phone heard, and the ids of messages they received are a trace.
    @Test("a wipe leaves nothing")
    func wipeLeavesNothing() {
        let seen = SeenSet(capacity: 1024, windowMillis: 60_000)
        for i in 0..<100 { _ = seen.seen(messageID(UInt64(i))) }
        #expect(seen.count > 0)

        seen.wipe()
        #expect(seen.count == 0)
        #expect(seen.seen(messageID(0)) == false)
    }
}

@Suite("The relay decision")
struct RouterTests {

    @Test("delivers once and deduplicates")
    func deliversOnceAndDeduplicates() {
        let clock = Clock()
        let router = Router(k: 3, now: clock.now, random: { 0 })
        let frame = Frame(kind: .channel, ttl: 4, id: messageID(1), body: Data("x".utf8))

        let first = router.handle(frame, from: "peer-a")
        #expect(first.deliver)
        #expect(first.relay)

        let second = router.handle(frame, from: "peer-b")
        #expect(second.deliver == false)
        #expect(second.relay == false)
        #expect(router.stats.duplicate == 1)
    }

    /// A phone must not show its owner its own message coming back from a neighbour.
    @Test("own messages come back as duplicates")
    func ownMessagesAreDuplicates() throws {
        let clock = Clock()
        let router = Router(now: clock.now, random: { 0 })

        let mine = router.originate(
            Frame(kind: .channel, ttl: 0, id: messageID(7), body: Data("hi".utf8)))
        #expect(mine.ttl == maxTTL)

        let echo = try #require(mine.hop())
        #expect(router.handle(echo, from: "peer-a").deliver == false)
    }

    @Test("a frame at the hop limit is delivered but not relayed")
    func hopLimitIsDeliveredNotRelayed() {
        let clock = Clock()
        let router = Router(now: clock.now, random: { 0 })
        let decision = router.handle(
            Frame(kind: .channel, ttl: 0, id: messageID(1)), from: "peer")

        #expect(decision.deliver)
        #expect(decision.relay == false)
        #expect(router.stats.expired == 1)
    }

    /// The feature works by hearing a token directly; a relayed one means walking towards
    /// somebody three hops away.
    @Test("a beacon is never relayed")
    func beaconIsNeverRelayed() {
        let clock = Clock()
        let router = Router(now: clock.now, random: { 0 })
        let beacon = Frame(kind: .beacon, ttl: 0, id: messageID(1), body: Data([1, 2, 3, 4]))

        let decision = router.handle(beacon, from: "peer")
        #expect(decision.deliver)
        #expect(decision.relay == false)
        #expect(beacon.beaconToken() == Data([1, 2, 3, 4]))
    }

    /// The storm control. In a packed pit almost nobody relays, and the message still
    /// crosses because there are hundreds of phones each rolling that die.
    @Test("the relay probability falls with density")
    func probabilityFallsWithDensity() {
        let clock = Clock()
        let router = Router(k: 3, now: clock.now, random: { 0.99 })

        #expect(router.relayProbability() == 1, "a node that has heard nobody relays")

        for i in 0..<300 { router.observe("peer-\(i)") }
        let probability = router.relayProbability()
        #expect(probability < 0.05)
        #expect(probability > 0)

        // An ordinary frame gives way; an announcement does not.
        #expect(
            router.handle(Frame(kind: .channel, ttl: 4, id: messageID(21)), from: "peer").relay
                == false)
        #expect(
            router.handle(
                Frame(kind: .announcement, flags: .priority, ttl: 4, id: messageID(22)),
                from: "peer"
            ).relay)
    }

    /// Without jitter every node that decided to relay transmits at the same instant, and
    /// on a shared medium simultaneous transmissions are collisions rather than deliveries.
    @Test("a relay is jittered")
    func relayIsJittered() {
        let clock = Clock()
        let router = Router(maxJitterMillis: 200, now: clock.now, random: { 0.5 })
        let decision = router.handle(
            Frame(kind: .channel, ttl: 4, id: messageID(1)), from: "peer")

        #expect(decision.relay)
        #expect(decision.afterMillis == 100)
    }

    /// Or the estimate only ever rises and the mesh goes quiet for the rest of the night.
    @Test("density forgets phones that walked away")
    func densityForgets() {
        let clock = Clock()
        let router = Router(k: 3, neighborWindowMillis: 30_000, now: clock.now, random: { 0 })

        for i in 0..<100 { router.observe("peer-\(i)") }
        #expect(router.neighborCount() > 90)

        clock.advance(60_000)
        #expect(router.neighborCount() == 0)
        #expect(router.relayProbability() == 1)
    }

    /// Carrying only helps where flooding does not reach, which is exactly where the
    /// density estimate is already low. Offering it in a dense crowd is the broadcast
    /// storm the density rule exists to prevent, through a side door.
    @Test("the carry buffer is only offered when sparse")
    func carryOnlyWhenSparse() {
        let clock = Clock()
        #expect(Router(k: 3, now: clock.now, random: { 0 }).shouldOfferCarry())

        let dense = Router(k: 3, now: clock.now, random: { 0 })
        for i in 0..<100 { dense.observe("peer-\(i)") }
        #expect(dense.shouldOfferCarry() == false)
    }

    /// A peer that has just walked up may only be in range for a few seconds, so a
    /// ten-second-old message matters more than a two-minute-old one. Frames added within
    /// the same millisecond need a tiebreaker, or "freshest first" silently becomes
    /// insertion order — which is oldest first.
    @Test("carried frames come back freshest first")
    func carriedFreshestFirst() {
        let clock = Clock()
        let router = Router(carryLimit: 4, now: clock.now, random: { 0 })

        for i in 0..<10 {
            _ = router.handle(
                Frame(kind: .channel, ttl: 4, id: messageID(UInt64(i))), from: "peer")
        }

        let carried = router.carriedFrames()
        #expect(carried.count == 4)
        #expect(hex(carried[0].id) == hex(messageID(9)))
    }

    @Test("carried frames expire")
    func carriedExpire() {
        let clock = Clock()
        let router = Router(carryForMillis: 60_000, now: clock.now, random: { 0 })
        _ = router.handle(Frame(kind: .channel, ttl: 4, id: messageID(1)), from: "peer")
        #expect(router.carriedFrames().count == 1)

        clock.advance(120_000)
        #expect(router.carriedFrames().count == 0)
    }

    @Test("a wipe leaves no trace of what the phone heard")
    func wipeClearsTheRouter() {
        let clock = Clock()
        let router = Router(now: clock.now, random: { 0 })
        for i in 0..<20 {
            router.observe("peer-\(i)")
            _ = router.handle(
                Frame(kind: .channel, ttl: 4, id: messageID(UInt64(i))), from: "peer")
        }

        router.wipe()

        #expect(router.carriedFrames().isEmpty)
        #expect(router.neighborCount() == 0)
        #expect(router.handle(Frame(kind: .channel, ttl: 4, id: messageID(0)), from: "peer").deliver)
    }

    @Test("a frame from an unknown version is dropped silently")
    func unknownVersionDropped() {
        let clock = Clock()
        let router = Router(now: clock.now, random: { 0 })
        var frame = Frame(kind: .channel, ttl: 4, id: messageID(1))
        frame.version = 99

        let decision = router.handle(frame, from: "peer")
        #expect(decision.deliver == false)
        #expect(decision.relay == false)
        #expect(router.stats.malformed == 1)
    }
}
